54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /** Maximum number of owners a single city may contain; creating an owner in a city that
64	     *  already has this many owners is rejected with 409 Conflict. */
65	    private static final int MAX_OWNERS_PER_CITY = 50;
66	
67	    /** Maximum number of owners that may be created on a single day (by registration date); creating
68	     *  an owner once this many owners already carry today's registration date is rejected with
69	     *  429 Too Many Requests. */
70	    private static final int MAX_OWNERS_PER_DAY = 100;
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    private final TelephoneNormalizer telephoneNormalizer;
81	
82	    private final HouseholdNormalizer householdNormalizer;
83	
84	    private final AddressNormalizer addressNormalizer;
85	
86	    public OwnerRestControllerV1(ClinicService clinicService,
87	                                 OwnerMapper ownerMapper,
88	                                 PetMapper petMapper,
89	                                 VisitMapper visitMapper,
90	                                 TelephoneNormalizer telephoneNormalizer,
91	                                 HouseholdNormalizer householdNormalizer,
92	                                 AddressNormalizer addressNormalizer) {
93	        this.clinicService = clinicService;
94	        this.ownerMapper = ownerMapper;
95	        this.petMapper = petMapper;
96	        this.visitMapper = visitMapper;
97	        this.telephoneNormalizer = telephoneNormalizer;
98	        this.householdNormalizer = householdNormalizer;
99	        this.addressNormalizer = addressNormalizer;
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
105	        Collection<Owner> owners;
106	        if (lastName != null) {
107	            owners = this.clinicService.findOwnerByLastName(lastName);
108	        } else {
109	            owners = this.clinicService.findAllOwners();
110	        }
111	        if (owners.isEmpty()) {
112	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
113	        }
114	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
120	        Owner owner = this.clinicService.findOwnerById(ownerId);
121	        if (owner == null) {
122	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
123	        }
124	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
130	        HttpHeaders headers = new HttpHeaders();
131	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
132	        normalizeOwnerFields(owner);
133	        // Enforce the pre-persistence policies that can reject the new owner outright.
134	        rejectDisallowedOwnerCreation(owner);
135	        // Identify any existing owners who share a household (same last name and address,
136	        // compared case-insensitively with collapsed whitespace) with the owner being created.
137	        List<Owner> householdMembers = sameHouseholdOwners(owner.getLastName(), owner.getAddress());
138	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
139	        // Reject creating an owner who shares a household with an existing owner, unless the
140	        // request explicitly opts in with 'sharesHousehold' true.
141	        if (!sharesHousehold && !householdMembers.isEmpty()) {
142	            throw new DuplicateHouseholdException(
143	                "An owner with the same last name and address already exists");
144	        }
145	        // When opting in and joining an existing household, assign the new owner and every
146	        // existing member the same stable household identifier derived from the last name and
147	        // address, so all owners of the household share one 'householdId'.
148	        if (sharesHousehold && !householdMembers.isEmpty()) {
149	            String householdId = householdNormalizer.householdId(owner.getLastName(), owner.getAddress());
150	            owner.setHouseholdId(householdId);
151	            for (Owner member : householdMembers) {
152	                if (!householdId.equals(member.getHouseholdId())) {
153	                    member.setHouseholdId(householdId);
154	                    this.clinicService.saveOwner(member);
155	                }
156	            }
157	        }
158	        // Record how many existing owners already share this owner's first and last name
159	        // (compared case-insensitively) before this create, fixed at creation time.
160	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
161	        // Assign the customer code '<CITY3>-<LAST3>-<NNNN>' from the city, last name and a
162	        // per-city sequence equal to one more than the owners already in that city, fixed at
163	        // creation time.
164	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
165	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
166	        // of the registration date's year (e.g. 'LON-SMI-0007-M26'), fixed at creation time.
167	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
168	        this.clinicService.saveOwner(owner);
169	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
170	        headers.setLocation(UriComponentsBuilder.newInstance()
171	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
172	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
173	    }
174	
175	    /**
176	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
177	     * outright, in order, before any derived fields are assigned or the owner is saved. An owner
178	     * in a city that already contains {@link #MAX_OWNERS_PER_CITY} owners is rejected with 409
179	     * ({@link CityCapacityExceededException}), and an owner whose normalized telephone is already
180	     * used by another owner is rejected with 409 ({@link DuplicateTelephoneException}). Grouping the
181	     * independent create-time rejection rules here keeps {@link #addOwner} focused on the household,
182	     * derived-field and persistence steps. The household rule stays in {@link #addOwner} itself
183	     * because it shares the matched-member lookup with the shared household-id assignment.
184	     *
185	     * @param owner the newly mapped and normalized owner being created
186	     */
187	    private void rejectDisallowedOwnerCreation(Owner owner) {
188	        // Reject creating an owner once 100 or more owners already carry today's registration date.
189	        if (countOwnersRegisteredToday() >= MAX_OWNERS_PER_DAY) {
190	            throw new DailyOwnerLimitExceededException(
191	                "The maximum number of owners that may be created today has already been reached");
192	        }
193	        // Reject creating an owner when the owner's city already contains 50 or more owners.
194	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
195	            throw new CityCapacityExceededException(
196	                "The city " + owner.getCity() + " already contains the maximum number of owners");
197	        }
198	        // Reject creating an owner whose normalized telephone is already used by another owner.
199	        String normalizedTelephone = owner.getTelephone();
200	        if (isTelephoneInUse(normalizedTelephone)) {
201	            throw new DuplicateTelephoneException(
202	                "An owner with telephone " + normalizedTelephone + " already exists");
203	        }
204	    }
205	
206	    /**
207	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
208	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
209	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
210	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
211	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
212	     * server's current date. Canonicalising the address here, before the household checks read it,
213	     * ensures duplicate detection and the shared household id both compare the normalized form.
214	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
215	     * duplicate, household and customer-code rules.
216	     *
217	     * @param owner the newly mapped owner to canonicalize
218	     */
219	    private void normalizeOwnerFields(Owner owner) {
220	        // Normalize the address on create so it is stored and returned in canonical form and every
221	        // later comparison (household duplicate detection and the shared household id) uses it.
222	        // A value that is blank after normalization is rejected with 400.
223	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
224	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
225	        // A value that cannot form a valid E.164 number is rejected with 400.
226	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
227	        // Store the (already syntactically validated) email lower-cased so it is persisted and
228	        // returned in canonical form. A missing email is left untouched.
229	        owner.setEmail(normalizeEmail(owner.getEmail()));
230	        // Default the registration date to the server's current date when the client did not
231	        // supply one, so it is persisted and returned in ISO 'YYYY-MM-DD' form.
232	        if (owner.getRegistrationDate() == null) {
233	            owner.setRegistrationDate(java.time.LocalDate.now());
234	        }
235	    }
236	
237	    /**
238	     * Lower-cases the supplied email address so it is stored and returned in canonical form.
239	     * Bean validation on the request DTO has already guaranteed that any non-null value is a
240	     * syntactically valid address (rejecting anything else with 400).
241	     *
242	     * @param email the email value (may be {@code null})
243	     * @return the lower-cased email, or {@code null} if the input was {@code null}
244	     */
245	    private String normalizeEmail(String email) {
246	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
247	    }
248	
249	    /**
250	     * Builds the customer code '<CITY3>-<LAST3>-<NNNN>' for a newly created owner, where CITY3 is
251	     * the upper-cased first three letters of the city, LAST3 is the upper-cased first three letters
252	     * of the last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than
253	     * the owners already in that city (e.g. 'LON-SMI-0007').
254	     *
255	     * @param city     the owner's city
256	     * @param lastName the owner's last name
257	     * @return the formatted customer code
258	     */
259	    private String nextCustomerCode(String city, String lastName) {
260	        String cityPrefix = city.substring(0, Math.min(3, city.length()))
261	            .toUpperCase(java.util.Locale.ROOT);
262	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length()))
263	            .toUpperCase(java.util.Locale.ROOT);
264	        int sequence = countOwnersInCity(city) + 1;
265	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
266	    }
267	
268	    /**
269	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
270	     * fix the per-city sequence of an owner's customer code at creation time.
271	     *
272	     * @param city the city of the owner being created
273	     * @return the number of existing owners in a matching city
274	     */
275	    private int countOwnersInCity(String city) {
276	        return (int) this.clinicService.findAllOwners().stream()
277	            .filter(existing -> existing.getCity() != null
278	                && existing.getCity().equalsIgnoreCase(city))
279	            .count();
280	    }
281	
282	    /**
283	     * Counts the existing owners whose registration date is today (the server's current date). Used
284	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
285	     * owners already carry today's registration date.
286	     *
287	     * @return the number of existing owners registered today
288	     */
289	    private int countOwnersRegisteredToday() {
290	        java.time.LocalDate today = java.time.LocalDate.now();
291	        return (int) this.clinicService.findAllOwners().stream()
292	            .filter(existing -> today.equals(existing.getRegistrationDate()))
293	            .count();
294	    }
295	
296	    /**
297	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
298	     * the last two digits of the registration date's year (e.g. 'LON-SMI-0007-M26').
299	     *
300	     * @param customerCode     the owner's customer code
301	     * @param registrationDate the owner's registration date
302	     * @return the formatted membership number
303	     */
304	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
305	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
306	    }
307	
308	    /**
309	     * Determines whether the given normalized telephone is already used by an existing owner.
310	     * Stored telephones are normalized to E.164 before comparison so values that differ only in
311	     * formatting (spaces, dashes, brackets) or in national vs. international notation are treated
312	     * as the same number.
313	     *
314	     * @param normalizedTelephone the normalized (E.164) telephone to look for
315	     * @return {@code true} if another owner already uses this telephone
316	     */
317	    private boolean isTelephoneInUse(String normalizedTelephone) {
318	        if (normalizedTelephone == null) {
319	            return false;
320	        }
321	        return this.clinicService.findAllOwners().stream()
322	            .map(Owner::getTelephone)
323	            .map(telephoneNormalizer::normalize)
324	            .anyMatch(normalizedTelephone::equals);
325	    }
326	
327	    /**
328	     * Returns the existing owners who share the given household, i.e. have the same last name and
329	     * the same address. The comparison delegates to {@link HouseholdNormalizer} so that values
330	     * differing only in letter case or in incidental whitespace are treated as the same household.
331	     *
332	     * @param lastName the last name of the owner being created
333	     * @param address  the address of the owner being created
334	     * @return the existing owners with a matching last name and address (possibly empty)
335	     */
336	    private List<Owner> sameHouseholdOwners(String lastName, String address) {
337	        String householdKey = householdNormalizer.householdKey(lastName, address);
338	        return this.clinicService.findAllOwners().stream()
339	            .filter(existing -> householdNormalizer
340	                .householdKey(existing.getLastName(), existing.getAddress()).equals(householdKey))
341	            .toList();
342	    }
343	
344	    /**
345	     * Counts the existing owners who share the given first and last name, compared
346	     * case-insensitively. Used to fix an owner's namesake count at creation time.
347	     *
348	     * @param firstName the first name of the owner being created
349	     * @param lastName  the last name of the owner being created
350	     * @return the number of existing owners with a matching first and last name
351	     */
352	    private int countNamesakes(String firstName, String lastName) {
353	        return (int) this.clinicService.findAllOwners().stream()
354	            .filter(existing -> existing.getFirstName() != null
355	                && existing.getFirstName().equalsIgnoreCase(firstName)
356	                && existing.getLastName() != null
357	                && existing.getLastName().equalsIgnoreCase(lastName))
358	            .count();
359	    }
360	
361	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
362	    @Override
363	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
364	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
365	        if (currentOwner == null) {
366	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
367	        }
368	        currentOwner.setAddress(ownerFieldsDto.getAddress());
369	        currentOwner.setCity(ownerFieldsDto.getCity());
370	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
371	        currentOwner.setLastName(ownerFieldsDto.getLastName());
372	        // Normalize the telephone to canonical E.164 form so it is stored and returned
373	        // consistently with create; an unformattable value is rejected with 400.
374	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
375	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
376	        this.clinicService.saveOwner(currentOwner);
377	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
378	    }
379	
380	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
381	    @Transactional
382	    @Override
383	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
384	        Owner owner = this.clinicService.findOwnerById(ownerId);
385	        if (owner == null) {
386	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
387	        }
388	        this.clinicService.deleteOwner(owner);
389	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
390	    }
391	
392	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
393	    @Override
394	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
395	        Owner owner = this.clinicService.findOwnerById(ownerId);
396	        if (owner == null) {
397	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
398	        }
399	        HttpHeaders headers = new HttpHeaders();
400	        Pet pet = petMapper.toPet(petFieldsDto);
401	        owner.setId(ownerId);
402	        pet.setOwner(owner);
403	        pet.getType().setName(null);
404	        this.clinicService.savePet(pet);
405	        PetDto petDto = petMapper.toPetDto(pet);
406	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
407	            .buildAndExpand(pet.getId()).toUri());
408	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
409	    }
410	
411	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
412	    @Override
413	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
414	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
415	        if (currentOwner != null) {
416	            Pet currentPet = this.clinicService.findPetById(petId);
417	            if (currentPet != null) {
418	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
419	                currentPet.setName(petFieldsDto.getName());
420	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
421	                this.clinicService.savePet(currentPet);
422	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
423	            }
424	        }
425	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
426	    }
427	
428	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
429	    @Override
430	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
431	        HttpHeaders headers = new HttpHeaders();
432	        Visit visit = visitMapper.toVisit(visitFieldsDto);
433	        Pet pet = new Pet();
434	        pet.setId(petId);
435	        visit.setPet(pet);
436	        this.clinicService.saveVisit(visit);
437	        VisitDto visitDto = visitMapper.toVisitDto(visit);
438	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
439	            .buildAndExpand(visit.getId()).toUri());
440	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
441	    }
442	
443	
444	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
445	    @Override
446	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
447	        Owner owner = this.clinicService.findOwnerById(ownerId);
448	        if (owner != null) {
449	            Pet pet = owner.getPet(petId);
450	            if (pet != null) {
451	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
452	            }
453	        }
454	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
455	    }
